{"sql": "-- Check how many srk_movies there are
WITH srk_movies AS (
    SELECT DISTINCT TRIM(mc.MID) FROM M_Cast mc WHERE TRIM(mc.PID) = 'nm0451321'
)
SELECT COUNT(*) FROM srk_movies"}

{"sql": "-- Check if Freida Pinto was in any SRK movie
WITH srk_movies AS (
    SELECT DISTINCT TRIM(mc.MID) AS mid FROM M_Cast mc WHERE TRIM(mc.PID) = 'nm0451321'
)
SELECT COUNT(*) FROM srk_movies WHERE mid IN (SELECT DISTINCT TRIM(mc.MID) FROM M_Cast mc WHERE TRIM(mc.PID) = 'nm2951768')"}
